def decode(encoded: str, original: str, message: str) -> str:
    # Initialize a dictionary to store the encoding mapping
    mapping = {}

    # Check if the encoder and original strings have the same length
    if len(encoded) != len(original):
        return "Failed"

    # Build the encoding mapping
    for i in range(len(encoded)):
        # If the encoded character is not already in the mapping, add it
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        # If the encoded character is already in the mapping and maps to a different letter, return "Failed"
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Create a list to store the decoded message
    decoded = []

    # Iterate through the encoded message and look up the decoded character in the mapping
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return "".join(decoded)
