    # Base case: if k is 1, then there is only 1 way to partition n into k parts
    if k == 1:
        return 1

    # Initialize a 2D array to store the results
    dp = [[0] * (n + 1) for _ in range(k)]

    # Fill in the initial values of the 2D array
    for i in range(k):
        dp[i][0] = 1

    # Fill in the rest of the 2D array using the recurrence relation
    for i in range(1, k):
        for j in range(1, n + 1):
            if j < x:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j - x] + dp[i][j - 1]

    # Return the result
    return dp[k - 1][n]
