def count_partitions(n, k, x):
    # Initialize a 2D array to store the results
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Initialize the first row with 1s
    for i in range(k + 1):
        dp[0][i] = 1

    # Fill in the table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            # If j is greater than i, then we can't form a partition of size j
            if j > i:
                dp[i][j] = dp[i - 1][j - 1]
            # If j is less than or equal to i, then we can form a partition of size j
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - j][j]

    # Return the last element of the last row
    return dp[n][k]
