def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table with -1 to indicate that a subproblem has not been solved yet
    for i in range(V + 1):
        for j in range(n + 1):
            dp[i][j] = -1

    # Initialize the base cases
    for i in range(n + 1):
        dp[0][i] = 0
    for j in range(V + 1):
        dp[j][0] = 0

    # Fill in the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # Consider not picking the current item
            not_picking = dp[i][j - 1]
            # Consider picking the current item
            picking = max(dp[i - volumes[j - 1]][j - 1], 0) + volumes[j - 1]
            dp[i][j] = max(not_picking, picking)

    return V - dp[V][n]
