def egcd(a, b):
    # Function to find the Extended Euclidean Algorithm of two numbers
    # Returns the gcd, x, and y of the equation ax + by = gcd(a, b)
    if a == 0:
        return (b, 0, 1)
    g, y, x = egcd(b % a, a)
    return (g, x - (b // a) * y, y)
